mapper.select:


    inner join sys_user u on u.user_name = inspectionplan.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    inspectionplan.del_flag = '0'
     and inspectionplan.name like concat('%', #{name}, '%')
     and inspectionplan.inspection_line = #{inspectionLine}
     and inspectionplan.type = #{type}
     and inspectionplan.plan_start_time = #{planStartTime}
     and inspectionplan.plan_end_time = #{planEndTime}
     and inspectionplan.inspection_start_time = #{inspectionStartTime}
     and inspectionplan.inspection_end_time = #{inspectionEndTime}
     and inspectionplan.inspector = #{inspector}
     and inspectionplan.status = #{status}



${params.dataScope}
order BY create_time desc
